import{_ as o,C as s,o as l,c as i,j as e,a as t,E as d,a3 as n}from"./chunks/framework.CZBGEXos.js";const x=JSON.parse('{"title":"Spreads","description":"","frontmatter":{},"headers":[],"relativePath":"ru/tools/spreads.md","filePath":"ru/tools/spreads.md"}'),h={name:"ru/tools/spreads.md"};function p(c,a,m,u,g,f){const r=s("Screenshot");return l(),i("div",null,[a[0]||(a[0]=e("h1",{id:"spreads",tabindex:"-1"},[t("Spreads "),e("a",{class:"header-anchor",href:"#spreads","aria-label":'Permalink to "Spreads"'},"​")],-1)),a[1]||(a[1]=e("p",null,[t("Spreads показывает "),e("strong",null,"одну и ту же монету по разной цене на разных биржах"),t(" прямо сейчас: насколько широк разрыв, как долго он открыт, а также объём и фандинг за каждой ценой.")],-1)),d(r,{src:"web-spreads",alt:"Spreads в веб-версии с несколькими карточками спредов",caption:"Spreads в веб-версии — в углу всплывающее окно нового листинга"}),a[2]||(a[2]=n('<div class="info custom-block"><p class="custom-block-title">Ранее Alerts</p><p>До октября 2026 этот инструмент назывался <strong>Alerts</strong> и также показывал новые листинги и ликвидации. Листинги теперь — <a href="/manual/ru/getting-started.html#всплывающие-окна-новых-листингов">всплывающие окна</a> во всех инструментах, а ликвидации переехали в <a href="/manual/ru/tools/ticks.html#ликвидации">Ticks</a>.</p></div><h2 id="как-читать-окно" tabindex="-1">Как читать окно <a class="header-anchor" href="#как-читать-окно" aria-label="Permalink to &quot;Как читать окно&quot;">​</a></h2><h3 id="панель-инструмента" tabindex="-1">Панель инструмента <a class="header-anchor" href="#панель-инструмента" aria-label="Permalink to &quot;Панель инструмента&quot;">​</a></h3><p>Панель показывает действующие настройки. В веб-версии каждый чип — быстрый фильтр, который можно изменить на месте:</p><ul><li><strong>Таймфрейм</strong> — интервал свечей графиков карточек, например <code>1m chart</code>.</li><li><strong>Spread ≥ …</strong> — <a href="#minimum-spread">минимальный спред</a>.</li><li><strong>Max age</strong> — <a href="#max-spread-age">max spread age</a>; <code>Any age</code>, когда выключено.</li><li><strong>Max width</strong> — <a href="#max-spread">max spread %</a>; <code>Any width</code>, когда выключено.</li><li><strong>Volume</strong> — <a href="#volume-filter">фильтр объёма</a>; <code>Any volume</code>, когда выключено.</li><li><strong>Сортировка</strong> — порядок карточек: <strong>Newest</strong>, <strong>Spread</strong>, <strong>Age</strong> или <strong>Volume</strong>.</li></ul><h3 id="порядок" tabindex="-1">Порядок <a class="header-anchor" href="#порядок" aria-label="Permalink to &quot;Порядок&quot;">​</a></h3><p>По умолчанию карточки упорядочены от новых, по <strong>времени открытия спреда</strong>. Карточка сохраняет место, пока обновляются её числа, так что лента не перемешивается, пока вы читаете. В веб-версии можно вместо этого сортировать по самому широкому спреду, самому долгому или наибольшему суммарному объёму.</p><h3 id="карточка-спреда" tabindex="-1">Карточка спреда <a class="header-anchor" href="#карточка-спреда" aria-label="Permalink to &quot;Карточка спреда&quot;">​</a></h3><ul><li><p><strong>Символ</strong> — нажмите, чтобы скопировать в буфер обмена.</p></li><li><p><strong>Возраст</strong> — как долго спред на уровне вашего порога или выше, например <code>12m</code> или <code>3h</code>.</p></li><li><p><strong>Спред</strong> — текущий максимальный разрыв цен между биржами в процентах.</p></li><li><p><strong>Строки бирж</strong> — по строке на каждую биржу, где есть монета, с цветной точкой как у её линии на графике:</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Значение</th></tr></thead><tbody><tr><td>Exchange</td><td>Откуда цена</td></tr><tr><td>24h vol</td><td>Объём биржи за 24 часа. Заливка показывает её долю в суммарном объёме монеты на этих биржах</td></tr><tr><td>Funding</td><td>Текущая ставка фандинга — зелёная, когда платят лонги, красная, когда шорты</td></tr><tr><td>Next</td><td>Время до следующей выплаты фандинга на этой бирже</td></tr></tbody></table></li><li><p><strong>График</strong> — по линии цены на каждую биржу, чтобы видеть, разрыв расширяется, сужается или держится.</p></li><li><p><strong>Полный экран</strong> — кнопка разворачивания открывает карточку на весь размер; см. <a href="#полноэкранныи-режим">Полноэкранный режим</a>.</p></li></ul><h4 id="приглушенные-карточки" tabindex="-1">Приглушённые карточки <a class="header-anchor" href="#приглушенные-карточки" aria-label="Permalink to &quot;Приглушённые карточки&quot;">​</a></h4><p>Карточка становится <strong>приглушённой</strong>, когда текущий спред опускается ниже вашего <a href="#minimum-spread">минимального спреда</a>. Спред ещё не закончился — сервер держит его открытым, пока он не пробудет ниже порога <strong>10 минут</strong>. Если он снова расширится, карточка снова засветится и сохранит свой возраст. Если нет — исчезнет из ленты.</p><p>Звук играет один раз на новый спред, а не снова, когда приглушённая карточка возвращается.</p><h4 id="как-считается-спред" tabindex="-1">Как считается спред <a class="header-anchor" href="#как-считается-спред" aria-label="Permalink to &quot;Как считается спред&quot;">​</a></h4><p>Процент — это <code>(самая высокая цена − самая низкая цена) ÷ самая низкая цена × 100</code> по всем биржам, которые сейчас дают цену этой монеты.</p><p>Это значение <strong>живое</strong>. Оно постоянно пересчитывается из тех же потоков бирж, что питают линии графика, так что показывает текущий разрыв, а не тот, что был в момент открытия.</p><p>Два вида цен не учитываются, потому что ни один из них — не разрыв, на котором можно торговать:</p><ul><li><strong>Замершая цена.</strong> Биржа, где за целую 5-минутную свечу не было ни одной сделки по монете, исключается из спреда — делистнутый контракт в расчёте часами транслирует последнюю цену.</li><li><strong>Другой актив с тем же названием.</strong> Цена, больше серединной по биржам более чем вдвое или меньше её половины, считается другой монетой с тем же тикером (например, фьючерс на акцию и криптотокен, оба <code>BB</code>) и исключается. Если остаются только две биржи и они так расходятся, монета не показывается вообще.</li></ul><div class="warning custom-block"><p class="custom-block-title">Спред — не гарантированная прибыль</p><p>Это разница между двумя котировками. Она ничего не говорит о том, можно ли на ней реально заработать — глубина стакана, комиссии, фандинг, время перевода и доступность вывода в расчёт не входят, а видимый разрыв может закрыться раньше, чем исполнится ордер. Воспринимайте это как сигнал посмотреть, а не как результат.</p></div><p>График намеренно увеличен с тесными полями цены, потому что разрыв между линиями бирж обычно мал относительно цены и при обычном масштабе был бы незаметен.</p><h3 id="полноэкранныи-режим" tabindex="-1">Полноэкранный режим <a class="header-anchor" href="#полноэкранныи-режим" aria-label="Permalink to &quot;Полноэкранный режим&quot;">​</a></h3><p>Кнопка разворачивания открывает карточку на весь размер: те же линии цен по биржам, строки бирж с объёмом и фандингом, текущий спред и его возраст. Таймфрейм выбирается вверху. В веб-версии полноэкранный график также имеет <a href="/manual/ru/getting-started.html#рисование-в-полноэкранном-режиме">инструменты рисования</a>; рисунки здесь хранятся для каждой монеты отдельно от других инструментов. Нажмите <kbd>Esc</kbd> или кнопку закрытия, чтобы выйти.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><p>Откройте настройки Spreads: иконка справа на панели инструмента (веб) или вкладка <strong>Spreads</strong> в главном окне (Windows).</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-cards" tabindex="-1">Max cards <a class="header-anchor" href="#max-cards" aria-label="Permalink to &quot;Max cards&quot;">​</a></h4><p>Сколько карточек показывает лента одновременно. Диапазон <strong>от 3 до 50</strong>, по умолчанию 9.</p><h4 id="chart-timeframe" tabindex="-1">Chart timeframe <a class="header-anchor" href="#chart-timeframe" aria-label="Permalink to &quot;Chart timeframe&quot;">​</a></h4><p>Интервал свечей для линий цен в карточках. Варианты: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code>, <code>1w</code>. По умолчанию <code>1m</code>.</p><p>Это меняет только график. На расчёт спреда и на то, какие спреды проходят, не влияет.</p><h3 id="spread-settings" tabindex="-1">Spread settings <a class="header-anchor" href="#spread-settings" aria-label="Permalink to &quot;Spread settings&quot;">​</a></h3><h4 id="minimum-spread" tabindex="-1">Minimum spread <a class="header-anchor" href="#minimum-spread" aria-label="Permalink to &quot;Minimum spread&quot;">​</a></h4><p>Спред, которого должна достичь монета, чтобы появиться. Диапазон <strong>от 1% до 10%</strong> с шагом 0,5%, по умолчанию 1%.</p><p>Спред, опустившийся ниже этого значения, <a href="#приглушенные-карточки">приглушается</a>, а не исчезает сразу. Он покидает ленту через 10 минут ниже порога.</p><h4 id="max-spread" tabindex="-1">Max spread % <a class="header-anchor" href="#max-spread" aria-label="Permalink to &quot;Max spread %&quot;">​</a></h4><p>Скрывает спреды шире этого значения. По умолчанию <strong>выключено</strong> (пусто). Кнопки − / + меняют на 5%, или введите любое значение.</p><p>Спред в сотни процентов почти никогда не является реальной возможностью. Сервер уже исключает <a href="#как-считается-спред">другие активы с тем же названием</a>, но ограничение всё равно помогает с остальным. <strong>50%</strong> — хорошая отправная точка.</p><h4 id="max-spread-age" tabindex="-1">Max spread age <a class="header-anchor" href="#max-spread-age" aria-label="Permalink to &quot;Max spread age&quot;">​</a></h4><p>Скрывает спреды, открытые дольше этого значения. Шаги: <strong>Off</strong>, 30m, 1h, 2h, 4h, 8h, 12h, 1d, 2d, 3d, 7d. По умолчанию Off.</p><p>Разрыв, который держится днями, обычно структурный — приостановленный вывод, другой токен, — а не тот, что закроется.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="new-spread-sound" tabindex="-1">New spread sound <a class="header-anchor" href="#new-spread-sound" aria-label="Permalink to &quot;New spread sound&quot;">​</a></h4><p>Воспроизводит звук, когда открывается новый спред. Включено по умолчанию.</p><h3 id="volume-filter" tabindex="-1">Volume filter <a class="header-anchor" href="#volume-filter" aria-label="Permalink to &quot;Volume filter&quot;">​</a></h3><h4 id="enable-volume-filter" tabindex="-1">Enable volume filter <a class="header-anchor" href="#enable-volume-filter" aria-label="Permalink to &quot;Enable volume filter&quot;">​</a></h4><p>Фильтрует спреды по объёму торгов за 24 часа. По умолчанию выключено.</p><div class="info custom-block"><p class="custom-block-title">Нужно две</p><p>Спред должен иметь <strong>как минимум две биржи</strong> с объёмом выше минимального, чтобы пройти фильтр. Это намеренно: разрыв цен имеет смысл, только если за обеими его сторонами есть реальная торговля.</p></div><h4 id="minimum-24h-volume" tabindex="-1">Minimum 24h volume <a class="header-anchor" href="#minimum-24h-volume" aria-label="Permalink to &quot;Minimum 24h volume&quot;">​</a></h4><p>Объём за 24 часа в USD, нужный бирже, чтобы её сторона спреда учитывалась. Введите сумму; по умолчанию <strong>$1 000 000</strong>.</p><p>Неактивно, пока фильтр объёма выключен.</p><div class="info custom-block"><p class="custom-block-title">Все эти фильтры работают на сервере</p><p>Минимальный спред, max spread %, max age и фильтр объёма применяются на сервере, так что скрытый спред вообще не доходит до приложения. Изменение значения действует в течение секунды.</p></div><h2 id="связанное" tabindex="-1">Связанное <a class="header-anchor" href="#связанное" aria-label="Permalink to &quot;Связанное&quot;">​</a></h2><ul><li><a href="/manual/ru/tools/knives.html">Knives</a> — движение цены на одной бирже, а не разрывы между биржами</li><li><a href="/manual/ru/tools/monitor.html">Monitor</a> — ранжированный обзор рынка</li><li><a href="/manual/ru/getting-started.html#всплывающие-окна-новых-листингов">Всплывающие окна новых листингов</a> — ранее часть этого инструмента</li></ul>',52))])}const q=o(h,[["render",p]]);export{x as __pageData,q as default};
